PAYLOAD=''
from pathlib import Path
from datetime import datetime, timezone
import subprocess,hashlib,json,gzip,base64,shutil,secrets,os,re,shlex,difflib
ROOT=Path('/var/www/marketplace.dieseldesigns.co')
def run(args,**kw):return subprocess.run(args,check=True,**kw)
def output(args):return subprocess.check_output(args,text=True).strip()
def note(message):print(message,flush=True)
def main():
    os.chdir(ROOT)
    if output(['git','branch','--show-current'])!='main':raise RuntimeError('Expected main branch.')
    if output(['git','rev-parse','HEAD'])!='da4967a7455276b11e53119e41c4c20e020e8b87':raise RuntimeError('Expected inspected main commit.')
    if not Path('public/assets').is_symlink() or Path('public/assets').resolve()!=(ROOT/'assets').resolve():raise RuntimeError('Asset layout changed.')
    allowed={'assets/final-giveaway-live.js', 'database/migrations/2026_10_27_final_giveaway_wheel.sql', 'app/Views/buyer/final_giveaway_prize.php', 'app/Services/FinalGiveawayRehearsalService.php', 'tests/FinalGiveawayWheelTest.php', 'app/Views/admin/final_giveaway_rehearsal.php', 'app/Views/public/final_giveaway.php', 'app/Views/partials/dashboard_nav.php', 'database/migrations/2026_10_27_final_wheel_manual_live.sql', 'app/Controllers/FinalGiveawayRehearsalController.php', 'public/index.php', 'assets/final-giveaway-admin.js', 'app/Services/FinalGiveawayService.php', 'app/Views/emails/final_giveaway_prize.php', 'app/Views/admin/final_giveaway.php', 'app/Views/public/home.php', 'app/Services/BuyerReferralGiveawayService.php', 'tests/FinalGiveawayRehearsalTest.php', 'database/migrations/2026_10_27_temporary_giveaway_rehearsal.sql', 'app/Controllers/FinalGiveawayController.php'}
    changed=set()
    for command in (['git','diff','--name-only','-z'],['git','diff','--cached','--name-only','-z'],['git','ls-files','--others','--exclude-standard','-z']):
        changed.update(filter(None,subprocess.check_output(command,text=True).split('\0')))
    if changed-allowed:raise RuntimeError('Unexpected changes: '+', '.join(sorted(changed-allowed)))
    expected={'app/Controllers/FinalGiveawayController.php': 'dbf9cf5972c26f02b4f5d2ac784f9601e24c47655864e390568604bd211bb288', 'app/Services/BuyerReferralGiveawayService.php': 'ad3e3a828a82f168b6e62bb4805d27c2903deb555790c15b5de4955d034bc123', 'app/Services/FinalGiveawayService.php': '26daca0254897cccaa49dd8c455511f0848a1850de047c328c253ee42853badb', 'app/Views/admin/final_giveaway.php': '2aa544d01c13226b8e127245651562d187b56a88a585166cc342dab30a7f9af0', 'app/Views/buyer/final_giveaway_prize.php': '4d7df0a421c7dbb3e5a806e4720e5d896993b7c21ff877fab8bddd073d209430', 'app/Views/emails/final_giveaway_prize.php': '419e7ce6c0284f0cbc5be3ea76ae95b947c86bdd5c572d95f2fca89cd81401a0', 'app/Views/partials/dashboard_nav.php': 'bd9e23a8c5179e1571d42fea81f4cb852435b5fa1ef2035c5fb32bca164252a0', 'app/Views/public/final_giveaway.php': '858b0ac804eb7e20b4b543a682116c8fe071cadac09ccf65f665404d64f7d58f', 'app/Views/public/home.php': '62fdb02d9fa4df718480912a102cf9e077c1f7e67233cc8b746bc511c904473c', 'database/migrations/2026_10_27_final_giveaway_wheel.sql': '0d0f238ac8a6f90c0217bf9fb080d60df439eeaf126af39143e80bf6fa196462', 'assets/final-giveaway-admin.js': '63a3251e702bcd98710d8568da8032e97bc5767fdc88a7a58c6b69063d52ef0f', 'assets/final-giveaway-live.js': '687a757a9b69248b79b7079dc2f49a7b068b903218d699b1ab41a99328859100', 'public/index.php': '93c0a23907d92cd71999b40655c1fff4707d1cb21bb7c924befd5abd7bd92b29', 'tests/FinalGiveawayWheelTest.php': '5ec04a0bcb4736cfb2e87b23f29a3cfdbee4ca5acc6124beeb0fe6505e99842e', 'app/Controllers/FinalGiveawayRehearsalController.php': '1decfb8c7b1340839c78bc04ef56a35acef50342b1e72b101400b33ee1a3edb8', 'app/Services/FinalGiveawayRehearsalService.php': 'ed4b10fcbfdb7cd45f3b53812ac1c4c100f49c765c15e02324502407f96abdc9', 'app/Views/admin/final_giveaway_rehearsal.php': '32117fa29c357553fd0978253a6eb76003a66b0a36befdf7d39402cd70c918c2', 'database/migrations/2026_10_27_final_wheel_manual_live.sql': 'ee03222c7408b4c57d64288150df1cda140a3820836448163a0935b7207de033', 'database/migrations/2026_10_27_temporary_giveaway_rehearsal.sql': 'a29c06831a860a1cf7800db970af6825856ab6a73302ad5ad3b1b673a59bf0e1', 'tests/FinalGiveawayRehearsalTest.php': '1a68006e06184f3266a475a13dfa12fd3973c143ca2b99eddb1ac52f34d0f8fb'}
    for name,digest in expected.items():
        if not Path(name).is_file() or hashlib.sha256(Path(name).read_bytes()).hexdigest()!=digest:raise RuntimeError('Installed source differs: '+name)
    manifest=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    originals={};candidates={}
    for name,item in manifest.items():
        path=Path(name)
        if item['before'] is None:
            if path.exists():raise RuntimeError('Unexpected file: '+name)
        else:
            original=path.read_bytes()
            if hashlib.sha256(original).hexdigest()!=item['before']:raise RuntimeError('Source differs: '+name)
            originals[name]=original
        candidate=item['content'].encode()
        if hashlib.sha256(candidate).hexdigest()!=item['after']:raise RuntimeError('Package integrity failed: '+name)
        candidates[name]=candidate
    unchanged=['app/Services/ReferralService.php','app/Services/PrizeWheelService.php','app/Controllers/PrizeWheelController.php','app/Services/GrandOpeningPassportService.php']
    protected={n:Path(n).read_bytes() for n in unchanged}
    backup=ROOT/'backups'/('step10-labeled-wheel-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    stage=backup/'candidate';stage.mkdir(parents=True)
    note('BACKUP / STAGING: '+str(backup))
    for name in (subprocess.check_output(['git','ls-files','-z'],text=True)+subprocess.check_output(['git','ls-files','--others','--exclude-standard','-z'],text=True)).split('\0'):
        if not name:continue
        p=Path(name)
        if p.suffix in ('.php','.sql') and p.parts[0] in ('app','public','tests','database'):
            target=stage/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,target)
    for name,data in candidates.items():
        target=stage/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
    note('STAGED PHP SYNTAX CHECKS')
    for name in candidates:
        if name.endswith('.php'):run(['php','-l',str(stage/name)])
    match=re.search(r'(?m)^\s*(?:export\s+)?DB_NAME\s*=\s*(.*?)\s*$',Path('.env').read_text())
    if not match:raise RuntimeError('DB_NAME not found.')
    values=shlex.split(match.group(1),comments=True)
    if len(values)!=1 or not re.fullmatch(r'[A-Za-z0-9_]+',values[0]):raise RuntimeError('Database name needs inspection.')
    db=values[0];mysql=['mysql','--protocol=socket','-u','root','--batch','--skip-column-names']
    socket=output(mysql+['-e','SELECT @@socket'])
    if not socket or ';' in socket or '\n' in socket:raise RuntimeError('MySQL socket needs inspection.')
    tables=output(mysql+[db,'-e',"SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE'"]).splitlines()
    newtables=['final_giveaway_settings','final_giveaway_draws','final_giveaway_audits']
    if set(newtables+['final_giveaway_rehearsal'])-set(tables):raise RuntimeError('Installed wheel tables missing.')
    if output(mysql+[db,'-e',"SHOW COLUMNS FROM final_giveaway_draws LIKE 'removed_at'"]):raise RuntimeError('Entry confirmation already installed; inspect before rerunning.')
    migration=candidates['database/migrations/2026_10_27_final_wheel_entry_confirmation.sql'].decode()
    for suite in ['BuyerReferralGiveawayTest.php','FinalGiveawayRehearsalTest.php']:
        testdb='cm_sale_test_'+secrets.token_hex(10);created=False
        try:
            note('ISOLATED TEST: '+suite+' — schema only, no customer records copied')
            run(mysql+['-e','CREATE DATABASE `'+testdb+'` CHARACTER SET utf8mb4']);created=True
            statements=[]
            for table in tables:
                if not re.fullmatch(r'[A-Za-z0-9_]+',table):raise RuntimeError('Invalid table identifier.')
                statements.append('CREATE TABLE `'+testdb+'`.`'+table+'` LIKE `'+db+'`.`'+table+'`;')
            run(mysql,input='\n'.join(statements),text=True)
            run(mysql+[testdb],input=migration,text=True)
            run(mysql+[testdb],input='INSERT INTO final_giveaway_settings(id) VALUES(1);',text=True)
            if suite=='BuyerReferralGiveawayTest.php':run(mysql+[testdb],input='INSERT INTO buyer_referral_giveaway_settings(id) VALUES(1);',text=True)
            env=os.environ.copy();env['CM_SALE_TEST_DSN']='mysql:unix_socket='+socket+';dbname='+testdb
            run(['php',str(stage/'tests'/suite)],env=env)
        finally:
            if created:run(mysql+['-e','DROP DATABASE `'+testdb+'`'])
    note('ALL PRE-INSTALL CHECKS PASSED — backing up changed files')
    for name,original in originals.items():
        if Path(name).read_bytes()!=original:raise RuntimeError('Source changed while testing: '+name)
        target=backup/'original'/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(name,target)
    # Schema backup only: this migration adds tables and does not change existing records.
    with (backup/'before-schema.sql').open('wb') as handle:
        run(['mysqldump','--protocol=socket','-u','root','--no-data','--skip-comments',db],stdout=handle)
    with (backup/'before-drawing-records.sql').open('wb') as handle:
        run(['mysqldump','--protocol=socket','-u','root','--no-create-info',db,'final_giveaway_draws'],stdout=handle)
    review=[]
    for name,data in candidates.items():review.extend(difflib.unified_diff(originals.get(name,b'').decode().splitlines(keepends=True),data.decode().splitlines(keepends=True),fromfile='a/'+name,tofile='b/'+name))
    (backup/'review.diff').write_text(''.join(review))
    installed=[]
    try:
        run(mysql+[db],input=migration,text=True)
        late=['app/Services/FinalGiveawayService.php','app/Services/FinalGiveawayRehearsalService.php','app/Views/public/final_giveaway.php','public/index.php']
        order=[n for n in candidates if n not in late]+late
        for name in order:
            if name in originals and Path(name).read_bytes()!=originals[name]:raise RuntimeError('Source changed before installation: '+name)
            if name not in originals and Path(name).exists():raise RuntimeError('File appeared before installation: '+name)
            path=Path(name);path.parent.mkdir(parents=True,exist_ok=True)
            installed.append(name)
            temporary=path.with_name(path.name+'.final-wheel-install')
            shutil.copy2(stage/name,temporary);os.replace(temporary,path)
        run(['git','diff','--check'])
        for name,data in candidates.items():
            if Path(name).read_bytes()!=data:raise RuntimeError('Installed file mismatch: '+name)
        for name,data in protected.items():
            if Path(name).read_bytes()!=data:raise RuntimeError('Protected existing feature changed: '+name)
    except Exception:
        for name in reversed(installed):
            original=backup/'original'/name
            if original.exists():shutil.copy2(original,name)
            else:Path(name).unlink(missing_ok=True)
        note('Site files restored. Entry-confirmation column retained; inspect before rerunning. Existing prizes and entries were not deleted.')
        raise
    note('INSTALLED: Creative Moth brand colors, labeled wheel slices, winner popup and admin-only Remove entry confirmation.')
    note('Live settings retained. Restart the shared test to preview fresh fake entries. Temporary test setup still requires removal before Step 10 completion.')
    note('ADMIN: https://creativemoth.com/admin/final-giveaway')
    note('VIEWER: https://creativemoth.com/live-giveaway')
    note('BACKUP: '+str(backup));note('REVIEW DIFF: '+str(backup/'review.diff'))
    run(['git','status','--short'])
if __name__=='__main__':main()
